    {
      "action": "update_status",
      "params": {
        "status": "reminded"
      },
      "why": "El cliente ya ha sido notificado y el estado debe reflejarlo."
    },
    {
      "action": "add_note",
      "params": {
        "note": "Según notificación del 29/08, los recordatorios a Elektro Bidasoa deben enviarse por SMS. Se enviará el mensaje correspondiente."
